import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');
const loadAnton = makeLoadFont('Anton');
const loadAudiowide = makeLoadFont('Audiowide');

// Module-level Google Font loading — handles delayRender/continueRender internally
const { fontFamily: bebasFamily } = loadBebas();
